// Adattatore T2 · integrazione: collega l'oracolo a `reportMarginalitaPeriodo` di `@/lib/report`,
// la stessa funzione che usa la pagina `/report/marginalita` (che non valida il periodo per conto
// proprio: la validazione `validaPeriodoMarginalita` avviene dentro la funzione, che restituisce
// l'esito nel campo `errore`). Solo rinomina dei campi e `Number(...)`.
import { reportMarginalitaPeriodo } from "@/lib/report";
import type {
	VoceClienteMarginalita,
	VoceCollaboratoreMarginalita,
	VoceOffertaMarginalita,
} from "@/domain/marginalita";
import { proiezioniBaseline } from "../shared/proiezioni-baseline";
import type {
	AdattatoreIntegrazione,
	ClienteMarginalita,
	CollaboratoreMarginalita,
	OffertaMarginalita,
} from "../contratto";

const numeroONull = (valore: string | null): number | null => (valore === null ? null : Number(valore));

function collaboratore(voce: VoceCollaboratoreMarginalita): CollaboratoreMarginalita {
	return {
		collaboratoreId: voce.collaboratoreId,
		ricavi: Number(voce.ricavi),
		costi: Number(voce.costi),
		margine: Number(voce.margine),
		marginePercentuale: numeroONull(voce.marginePercentuale),
	};
}

function offerta(voce: VoceOffertaMarginalita): OffertaMarginalita {
	return {
		offertaId: voce.offertaId,
		ricavi: Number(voce.ricavi),
		costi: Number(voce.costi),
		margine: Number(voce.margine),
		marginePercentuale: numeroONull(voce.marginePercentuale),
		perCollaboratore: voce.perCollaboratore.map(collaboratore),
	};
}

function cliente(voce: VoceClienteMarginalita): ClienteMarginalita {
	return {
		clienteId: voce.clienteId,
		ricavi: Number(voce.ricavi),
		costi: Number(voce.costi),
		margine: Number(voce.margine),
		marginePercentuale: numeroONull(voce.marginePercentuale),
		perOfferta: voce.perOfferta.map(offerta),
		perCollaboratore: voce.perCollaboratore.map(collaboratore),
	};
}

export const adattatoreIntegrazione: AdattatoreIntegrazione = {
	async reportMarginalita(da, a) {
		const risultato = await reportMarginalitaPeriodo(da, a);
		if (risultato.errore !== null) return { rifiutato: true, motivo: risultato.errore };
		return { perCliente: risultato.perCliente.map(cliente) };
	},
	// `marginePercentuale` è la stringa di (margine / ricavi × 100).toFixed(1): 37,5 % → "37.5".
	scalaPercentuale: "punti",
	// `reportFatturazioneClientiMese` è invariato rispetto alla baseline.
	importiFatturazioneCliente: proiezioniBaseline.importiFatturazioneCliente,
	// L'enum `Ruolo` resta AMMINISTRATORE | COLLABORATORE: nessun ruolo per utenti esterni.
	ruoloUtenteCliente: null,
};
EOF
