// Adattatore T2 · browser: pagina `/report/marginalita` (page.tsx + report-marginalita.tsx) e voce
// «Marginalità» della sidebar del back-office (console-sidebar.tsx).
import type { Page } from "@playwright/test";
import type { AdattatoreBrowser, TokenMese } from "../contratto";

const intestazioneReport = (page: Page) =>
	page.getByRole("heading", { name: "Analisi della marginalità", exact: true });

const urlDelPeriodo = (da: TokenMese, a: TokenMese) => (url: URL) =>
	url.pathname === "/report/marginalita" && url.searchParams.get("da") === da && url.searchParams.get("a") === a;

export const adattatoreBrowser: AdattatoreBrowser = {
	async apriReport(page, da, a) {
		await page.goto(`/report/marginalita?da=${da}&a=${a}`);
		await intestazioneReport(page).waitFor({ state: "visible" });
	},

	async impostaPeriodoDaInterfaccia(page, da, a) {
		const form = page.getByRole("form", { name: "Periodo di analisi", exact: true });
		await form.getByLabel("Dal mese", { exact: true }).fill(da);
		await form.getByLabel("Al mese", { exact: true }).fill(a);
		await form.getByRole("button", { name: "Aggiorna analisi", exact: true }).click();
		await page.waitForURL(urlDelPeriodo(da, a));
		await intestazioneReport(page).waitFor({ state: "visible" });
	},

	async sezioneCliente(page, clienteId, ragioneSociale) {
		const sezione = page.getByTestId(`marginalita-cliente-${clienteId}`);
		await sezione.waitFor({ state: "visible" });
		// Dettaglio collaboratori in un <details> nativo chiuso di default: lo si espande dal suo summary.
		const dettaglio = sezione.locator("details");
		if ((await dettaglio.getAttribute("open")) === null) {
			await sezione.getByText(`Dettaglio collaboratori ${ragioneSociale}`, { exact: true }).click();
			await sezione.getByRole("table", { name: `Collaboratori ${ragioneSociale}`, exact: true }).waitFor({ state: "visible" });
		}
		return sezione;
	},

	percorsoBackOffice: () => "/anagrafiche",

	collegamentoAlReport: (page) =>
		page
			.getByRole("navigation", { name: "Navigazione principale", exact: true })
			.getByRole("link", { name: "Marginalità", exact: true }),

	contenitoreReport: (page) => intestazioneReport(page),
};
EOF
